    /** Token `label`; its usage note is in reference/design-system/tokens.json. */
    public val label: OldgeTypeStyle =
        OldgeTypeStyle(OldgeFontFamilyKey.Ui, 0.8125f, 1f, 700, 0f)

    /** Token `caption`; its usage note is in reference/design-system/tokens.json. */
    public val caption: OldgeTypeStyle =
        OldgeTypeStyle(OldgeFontFamilyKey.Ui, 0.75f, 1f, 400, 0f)

    /** Token `readout`; its usage note is in reference/design-system/tokens.json. */
