/**
 * Every generated value by its design-system token name, per skin where it varies. It points at
 * the properties above rather than restating them, so a test that compares it with tokens.json
 * tests the properties.
 */
internal object OldgeTokenIndex {
    val skins: List<String> = listOf("toxic", "media", "crystal")

    fun colors(skin: String): Map<String, Color> {
        val c = when (skin) {
            "toxic" -> OldgeColors.Toxic
            "media" -> OldgeColors.Media
            "crystal" -> OldgeColors.Crystal
            else -> error("no skin $skin")
        }
        return mapOf(
            "body-hi" to c.bodyHi,
            "ground" to c.ground,
            "glow" to c.glow,
            "surface" to c.surface,
            "surface-2" to c.surface2,
            "well" to c.well,
            "ink" to c.ink,
            "ink-muted" to c.inkMuted,
            "line" to c.line,
            "edge" to c.edge,
            "gloss" to c.gloss,
            "bezel-hi" to c.bezelHi,
            "bezel" to c.bezel,
            "bezel-lo" to c.bezelLo,
            "on-bezel" to c.onBezel,
            "chrome-hi" to c.chromeHi,
            "chrome-lo" to c.chromeLo,
            "on-chrome" to c.onChrome,
            "pill-hi" to c.pillHi,
            "pill-lo" to c.pillLo,
            "on-pill" to c.onPill,
            "accent-hi" to c.accentHi,
            "accent" to c.accent,
            "accent-lo" to c.accentLo,
            "on-accent" to c.onAccent,
            "accent-rim" to c.accentRim,
            "accent-ink" to c.accentInk,
            "select" to c.select,
            "on-select" to c.onSelect,
            "focus" to c.focus,
            "success" to c.success,
            "warning" to c.warning,
            "danger" to c.danger,
            "lcd" to c.lcd,
            "lcd-ink" to c.lcdInk,
            "lcd-dim" to c.lcdDim,
            "lcd-ghost" to c.lcdGhost,
            "meter-low" to c.meterLow,
            "meter-mid" to c.meterMid,
            "meter-peak" to c.meterPeak,
            "grain" to c.grain,
            "bezel-weave" to c.bezelWeave,
            "bezel-speckle" to c.bezelSpeckle,
            "balloon" to c.balloon,
            "on-balloon" to c.onBalloon,
            "balloon-mark" to c.balloonMark,
        )
    }

    fun shadows(skin: String): Map<String, List<OldgeShadow>> {
        val s = when (skin) {
            "toxic" -> OldgeShadows.Toxic
            "media" -> OldgeShadows.Media
            "crystal" -> OldgeShadows.Crystal
            else -> error("no skin $skin")
        }
        return mapOf(
            "shadow-raised" to s.raised,
            "shadow-sunken" to s.sunken,
            "shadow-bezel" to s.bezel,
            "shadow-orb" to s.orb,
            "shadow-window" to s.window,
            "shadow-balloon" to s.balloon,
            "shadow-lcd-glow" to s.lcdGlow,
        )
    }

    val spacing: Map<String, Dp> =
        mapOf(
            "space-1" to OldgeSpacing.space1,
            "space-2" to OldgeSpacing.space2,
            "space-3" to OldgeSpacing.space3,
            "space-4" to OldgeSpacing.space4,
            "space-5" to OldgeSpacing.space5,
            "space-6" to OldgeSpacing.space6,
            "hit-min" to OldgeSpacing.hitMin,
        )

    val radius: Map<String, Dp> =
        mapOf(
            "radius-xs" to OldgeRadii.xs,
            "radius-sm" to OldgeRadii.sm,
            "radius-md" to OldgeRadii.md,
            "radius-lg" to OldgeRadii.lg,
            "radius-xl" to OldgeRadii.xl,
            "radius-pill" to OldgeRadii.pill,
        )

    val duration: Map<String, Int> =
        mapOf(
            "dur-instant" to OldgeDurations.instant,
            "dur-fast" to OldgeDurations.fast,
            "dur-base" to OldgeDurations.base,
            "dur-slow" to OldgeDurations.slow,
            "dur-press" to OldgeDurations.press,
            "dur-loop" to OldgeDurations.loop,
        )

    val easing: Map<String, Easing> =
        mapOf(
            "ease-spring" to OldgeEasings.spring,
            "ease-bounce" to OldgeEasings.bounce,
            "ease-out" to OldgeEasings.out,
            "ease-linear" to OldgeEasings.linear,
        )

    val type: Map<String, OldgeTypeStyle> =
        mapOf(
            "display" to OldgeTypeStyles.display,
            "heading" to OldgeTypeStyles.heading,
            "title" to OldgeTypeStyles.title,
            "body" to OldgeTypeStyles.body,
            "body-strong" to OldgeTypeStyles.bodyStrong,
            "button" to OldgeTypeStyles.button,
            "label" to OldgeTypeStyles.label,
            "caption" to OldgeTypeStyles.caption,
            "readout" to OldgeTypeStyles.readout,
            "readout-sm" to OldgeTypeStyles.readoutSm,
            "pixel-tag" to OldgeTypeStyles.pixelTag,
        )
}
